//! 🧪️ An actual terminal child records its original refusal before unwinding.
use super::*;
use semio_framework_value_control_contract as core;
use semio_framework_value_testing_effect_bank::{EffectBank,Wallet};
use std::sync::{Arc,atomic::{AtomicUsize,Ordering}};
struct Child{error:Option<ValueError>,calls:Arc<AtomicUsize>,recoveries:Arc<AtomicUsize>}
impl ErasedSnapshotRetirement for Child{
 fn native_header_release(&self)->Option<crate::RetirementHeaderRelease>{self.terminal_is_empty().then(||unsafe{crate::RetirementHeaderRelease::native(self,0,0)})}
 fn next_copy_byte_demand(&self)->Result<usize,ValueError>{Ok(0)}
 fn next_capacity_byte_demand(&self,_:usize)->Result<usize,ValueError>{Ok(0)}
 fn next_release_byte_demand(&self)->Result<usize,ValueError>{Ok(0)}
 fn next_depth_demand(&self)->Result<usize,ValueError>{Ok(1)}
 fn next_demand(&self,_:usize)->Result<RetirementDemand,ValueError>{Ok(RetirementDemand{depth:1,..Default::default()})}
 fn next_computational_work(&self,_:usize)->Result<u64,ValueError>{Ok(1)}
 fn terminal_is_empty(&self)->bool{self.error.is_none()}
 fn close_step(&mut self,_body:usize,_:&mut RetainedAllocationEffect<'_>)->crate::OriginalRetirementPoll{panic!("owned child close bypassed original reply")}
 fn close_into<'r>(&mut self,_body:usize,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,OriginalRetirementFailure>,ValueError>{self.calls.fetch_add(1,Ordering::SeqCst);assert!(effect.performed(1)?);reply.complete(Err(self.error.take().expect("original child refusal").into()));panic!("child unwinds after actual reply")}
 fn recover_close_into<'r>(&mut self,_body:usize,_:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,OriginalRetirementFailure>,ValueError>{self.recoveries.fetch_add(1,Ordering::SeqCst);Ok(reply.pending())}
}
struct Parent{slot:Option<Box<Child>>,close:FactoryTicketClose}
impl core::OriginalEffectProducer for Parent{
 type Output=RetainedCloneStep;type Failure=OriginalRetirementFailure;type Context<'a,'b>=usize where 'b:'a;
 fn validate_context<'a,'b>(&self,_:&Self::Context<'a,'b>)->Result<(),ValueError>where 'b:'a{Ok(())}
 fn source_turn<'a,'b>(&self,_:&Self::Context<'a,'b>)->Option<core::OriginalSourceTurnIdentity>where 'b:'a{None}
 fn receive<'r,'a,'b>(&mut self,body:&mut Self::Context<'a,'b>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,Self::Output,Self::Failure>)->Result<OriginalEffectReplyComplete<'r,Self::Output,Self::Failure>,ValueError>where 'b:'a{self.close.close_into(&mut self.slot,*body,effect,reply)}
 fn recover<'r,'a,'b>(&mut self,body:&mut Self::Context<'a,'b>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,Self::Output,Self::Failure>)->Result<OriginalEffectReplyComplete<'r,Self::Output,Self::Failure>,ValueError>where 'b:'a{self.close.recover_close_into(&mut self.slot,*body,effect,reply)}
}
#[test]
fn ticket_close_recovers_original_recorded_refusal_before_terminal_shell_release(){
 let law:serde_json::Value=serde_json::from_str(include_str!("case.json")).unwrap();let mut body=law["selectedBody"].as_u64().unwrap()as usize;let calls=Arc::new(AtomicUsize::new(0));let recoveries=Arc::new(AtomicUsize::new(0));let error=ValueError::new(crate::ValueRefusalKind::Canceled,law["refusal"].as_str().unwrap().to_owned());let pointer=error.message.as_ptr();let mut parent=core::OriginalEffectAuthority::new(Parent{slot:Some(Box::new(Child{error:Some(error),calls:calls.clone(),recoveries:recoveries.clone()})),close:FactoryTicketClose::default()});let mut bank=EffectBank::new(Wallet::from_profile(&serde_json::json!({"items":16,"copyBytes":4096,"capacityBytes":4096,"releaseBytes":4096,"depth":8,"fuel":law["fuel"]})));let mut action=None;
 let demand=parent.inspect(|p|p.close.next_demand(&p.slot,body).unwrap());let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:demand.copy_bytes,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth};let interrupted=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||bank.run::<RetainedCloneStep,OriginalRetirementFailure>(grant,1,|effect|{parent.drive(&mut body,effect,&mut action).unwrap();panic!("recorded child must interrupt first")})));assert!(interrupted.is_err());assert_eq!(calls.load(Ordering::SeqCst),1);assert!(parent.inspect(|p|p.close.reply.is_some()&&p.slot.as_ref().unwrap().terminal_is_empty()));let mut foreign=law["foreignBody"].as_u64().unwrap()as usize;assert!(parent.inspect(|p|p.close.next_demand(&p.slot,foreign).is_err()));assert!(parent.inspect(|p|p.close.next_work(&p.slot,foreign).is_err()));let (denied,marker)=bank.run::<(),ValueError>(grant,1,|effect|{let before=effect.performed_work();assert_eq!(parent.drive(&mut foreign,effect,&mut action).unwrap_err().kind,crate::ValueRefusalKind::InvariantViolated);core::RetainedWorkPoll::Pending{work:effect.performed_work()-before}});assert_eq!(marker,None);assert!(matches!(denied,core::RetainedWorkPoll::Pending{work:0}));assert!(bank.has_pending_action());assert!(parent.inspect(|p|p.close.reply.is_some()));
 let (poll,marker)=bank.run(grant,1,|effect|{let before=effect.performed_work();assert!(parent.drive(&mut body,effect,&mut action).unwrap());let mut output=None;assert!(action.as_mut().unwrap().transfer_reply(&mut output).unwrap());core::RetainedWorkPoll::Complete(core::RetainedWorkOutcome{result:output.take().unwrap(),work:effect.performed_work()-before})});assert_eq!(marker,None);let core::RetainedWorkPoll::Complete(turn)=poll else{panic!("actual recorded child reply remains pending")};assert_eq!(turn.work,u128::from(law["reportedRecoveryWork"].as_u64().unwrap()));assert_eq!(turn.result.err().unwrap().primary().unwrap().message.as_ptr(),pointer);assert_eq!(bank.take_admitted(),Some(true));parent.finish(&mut action).unwrap();assert!(parent.inspect(|p|p.close.is_empty()&&p.slot.is_some()));
 let demand=parent.inspect(|p|p.close.next_demand(&p.slot,body).unwrap());let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:demand.copy_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth,..Default::default()};let ((poll,_),heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||bank.run(grant,1,|effect|{let before=effect.performed_work();assert!(parent.drive(&mut body,effect,&mut action).unwrap());let mut output=None;assert!(action.as_mut().unwrap().transfer_reply(&mut output).unwrap());core::RetainedWorkPoll::Complete(core::RetainedWorkOutcome{result:output.take().unwrap(),work:effect.performed_work()-before})}));let core::RetainedWorkPoll::Complete(turn)=poll else{panic!("native shell release cannot suspend")};bank.post(turn.result.unwrap().progress(),grant,heap);assert_eq!(bank.take_admitted(),Some(true));parent.finish(&mut action).unwrap();assert!(parent.inspect(|p|p.slot.is_none()&&p.close.is_empty()));assert_eq!(calls.load(Ordering::SeqCst),law["receive"].as_u64().unwrap()as usize);assert_eq!(recoveries.load(Ordering::SeqCst),law["recover"].as_u64().unwrap()as usize);assert!(parent.into_producer().is_ok());
}

#[test]
fn native_header_authenticates_actual_box_type_layout_and_address(){
 use std::sync::atomic::{AtomicUsize,Ordering};static DROPS:AtomicUsize=AtomicUsize::new(0);
 struct Header(u64);impl Drop for Header{fn drop(&mut self){assert!(self.0!=0);DROPS.fetch_add(1,Ordering::SeqCst);}}
 struct Twin(u64);
 macro_rules! erased{($kind:ty)=>{impl ErasedSnapshotRetirement for $kind{fn terminal_is_empty(&self)->bool{true}fn next_copy_byte_demand(&self)->Result<usize,ValueError>{Ok(0)}fn next_capacity_byte_demand(&self,_:usize)->Result<usize,ValueError>{Ok(0)}fn next_release_byte_demand(&self)->Result<usize,ValueError>{Ok(0)}fn next_depth_demand(&self)->Result<usize,ValueError>{Ok(1)}fn close_step(&mut self,_body:usize,_:&mut RetainedAllocationEffect<'_>)->crate::OriginalRetirementPoll{panic!("unknown native header cannot use an owned callback")}}};}erased!(Header);erased!(Twin);
 fn run<T:ErasedSnapshotRetirement+?Sized>(bank:&mut EffectBank,release:&crate::RetirementHeaderRelease,slot:&mut Option<Box<T>>,demand:RetirementDemand,maximum:u64)->Result<RetainedCloneProgress,OriginalRetirementFailure>{let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:demand.copy_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth,..Default::default()};let mut reply=None;let((poll,marker),heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||bank.run(grant,maximum,|effect|{let before=effect.performed_work();let result=release.release_into(slot,effect,OriginalEffectReply::borrow(&mut reply).unwrap());let result=match result{Ok(complete)=>{drop(complete);reply.take().unwrap()},Err(error)=>Err(error.into())};core::RetainedWorkPoll::Complete(core::RetainedWorkOutcome{result,work:effect.performed_work()-before})}));assert_eq!(marker,None);let core::RetainedWorkPoll::Complete(turn)=poll else{panic!("native header cannot leave a producer pending")};assert_eq!(bank.take_admitted(),if turn.work==0{None}else{Some(true)});match turn.result{Ok(step)=>{let p=step.progress();bank.post(p,grant,heap);Ok(p)},Err(error)=>{assert_eq!(heap,(0,0));Err(error)}}}
 let all:serde_json::Value=serde_json::from_str(include_str!("case.json")).unwrap();let law=&all["header"];DROPS.store(0,Ordering::SeqCst);let mut a=Some(Box::new(Header(73)));let mut b=Some(Box::new(Header(91)));let mut twin=Some(Box::new(Twin(73)));assert_eq!(std::mem::size_of::<Header>(),std::mem::size_of::<Twin>());let pointer=std::ptr::from_ref(a.as_ref().unwrap().as_ref());let unknown=super::super::factory_ticket_demands(a.as_ref().unwrap(),4096).unwrap_err();assert_eq!(unknown.kind,crate::ValueRefusalKind::UnsupportedOwner);assert_eq!(std::ptr::from_ref(a.as_ref().unwrap().as_ref()),pointer);assert_eq!(DROPS.load(Ordering::SeqCst),0);
 let mut bank=EffectBank::new(Wallet::from_profile(&serde_json::json!({"items":16,"copyBytes":4096,"capacityBytes":4096,"releaseBytes":4096,"depth":8,"fuel":all["fuel"]})));let release=unsafe{crate::RetirementHeaderRelease::native(a.as_ref().unwrap().as_ref(),0,1)};let d=release.demand(a.as_ref().unwrap().as_ref()).unwrap();assert_eq!(release.work().unwrap(),law["work"].as_u64().unwrap());
 assert_eq!(run(&mut bank,&release,&mut b,d,release.work().unwrap()).unwrap_err().primary().unwrap().kind,crate::ValueRefusalKind::InvariantViolated);assert!(b.is_some());assert_eq!(run(&mut bank,&release,&mut twin,d,release.work().unwrap()).unwrap_err().primary().unwrap().kind,crate::ValueRefusalKind::InvariantViolated);assert!(twin.is_some());assert_eq!(DROPS.load(Ordering::SeqCst),0);
 let mut denied=d;denied.release_bytes=0;assert_eq!(run(&mut bank,&release,&mut a,denied,release.work().unwrap()).unwrap(),RetainedCloneProgress::default());assert!(a.is_some());assert_eq!(DROPS.load(Ordering::SeqCst),0);assert_eq!(run(&mut bank,&release,&mut a,d,0).unwrap(),RetainedCloneProgress::default());assert!(a.is_some());
 run(&mut bank,&release,&mut a,d,release.work().unwrap()).unwrap();assert!(a.is_none());let release=unsafe{crate::RetirementHeaderRelease::native(b.as_ref().unwrap().as_ref(),0,1)};let d=release.demand(b.as_ref().unwrap().as_ref()).unwrap();run(&mut bank,&release,&mut b,d,release.work().unwrap()).unwrap();let release=unsafe{crate::RetirementHeaderRelease::native(twin.as_ref().unwrap().as_ref(),0,0)};let d=release.demand(twin.as_ref().unwrap().as_ref()).unwrap();run(&mut bank,&release,&mut twin,d,release.work().unwrap()).unwrap();assert!(b.is_none()&&twin.is_none());assert_eq!(DROPS.load(Ordering::SeqCst),law["drops"].as_u64().unwrap()as usize);assert_eq!(bank.wallet().remaining_work(),all["fuel"].as_u64().unwrap()-2*law["work"].as_u64().unwrap()-1);
}
